func TestRoles(t *testing.T) {
	for _, c := range []struct {
		route string
		role  string
		req   apiCase
	}{
		{"get_routing", "operator", getRoutingBaseline},
		{"list_tasks", "operator", listTasksBaseline},
		{"get_task", "operator", getTaskBaseline},
		{"list_runs", "operator", listRunsBaseline},
		{"list_audit", "operator", listAuditBaseline},
		{"list_secrets", "operator", listSecretsBaseline},
		{"put_secret", "admin", putSecretBaseline},
		{"rotate_secret", "admin", rotateSecretBaseline},
		{"delete_secret", "admin", deleteSecretBaseline},
		{"list_tokens", "operator", listTokensBaseline},
		{"issue_token", "admin", issueTokenBaseline},
		{"revoke_token", "admin", revokeTokenBaseline},
	} {
		t.Run(c.route, func(t *testing.T) {
			svc := &fakeService{}
			wantProblem(t, do(svc, "", c.req), http.StatusUnauthorized)
			wantProblem(t, do(svc, "nobody", c.req), http.StatusForbidden)
			if len(svc.calls) != 0 {
				t.Fatalf("the service was called without the role: %v", svc.calls)
			}
			if rec := do(svc, c.role, c.req); rec.Code >= 400 {
				t.Fatalf("the route's own role was refused: %d %s", rec.Code, rec.Body)
			}
		})
	}
}

// TestRouteTable: the table lists every route once, in the mux's own terms.
func TestRouteTable(t *testing.T) {
	if len(Routes) != 12 {
		t.Fatalf("%d routes, want 12", len(Routes))
	}
	if r := Routes[0]; r.Name != "get_routing" || r.Method != "GET" || r.Path != "/api/v1/routing" || r.Role != "operator" || r.Call != "routing_view" || r.Status != 200 {
		t.Errorf("Routes[0] = %+v", r)
	}
	if r := Routes[1]; r.Name != "list_tasks" || r.Method != "GET" || r.Path != "/api/v1/tasks" || r.Role != "operator" || r.Call != "task_from_issue" || r.Status != 200 {
		t.Errorf("Routes[1] = %+v", r)
	}
	if r := Routes[2]; r.Name != "get_task" || r.Method != "GET" || r.Path != "/api/v1/tasks/{number}" || r.Role != "operator" || r.Call != "task_from_issue" || r.Status != 200 {
		t.Errorf("Routes[2] = %+v", r)
	}
	if r := Routes[3]; r.Name != "list_runs" || r.Method != "GET" || r.Path != "/api/v1/runs" || r.Role != "operator" || r.Call != "page_size" || r.Status != 200 {
		t.Errorf("Routes[3] = %+v", r)
	}
	if r := Routes[4]; r.Name != "list_audit" || r.Method != "GET" || r.Path != "/api/v1/audit" || r.Role != "operator" || r.Call != "page_size" || r.Status != 200 {
		t.Errorf("Routes[4] = %+v", r)
	}
	if r := Routes[5]; r.Name != "list_secrets" || r.Method != "GET" || r.Path != "/api/v1/secrets" || r.Role != "operator" || r.Call != "credentials_of_kind" || r.Status != 200 {
		t.Errorf("Routes[5] = %+v", r)
	}
	if r := Routes[6]; r.Name != "put_secret" || r.Method != "POST" || r.Path != "/api/v1/secrets" || r.Role != "admin" || r.Call != "credential_problem" || r.Status != 204 {
		t.Errorf("Routes[6] = %+v", r)
	}
	if r := Routes[7]; r.Name != "rotate_secret" || r.Method != "PUT" || r.Path != "/api/v1/secrets/{name}" || r.Role != "admin" || r.Call != "credential_problem" || r.Status != 204 {
		t.Errorf("Routes[7] = %+v", r)
	}
	if r := Routes[8]; r.Name != "delete_secret" || r.Method != "DELETE" || r.Path != "/api/v1/secrets/{name}" || r.Role != "admin" || r.Call != "credential_problem" || r.Status != 204 {
		t.Errorf("Routes[8] = %+v", r)
	}
	if r := Routes[9]; r.Name != "list_tokens" || r.Method != "GET" || r.Path != "/api/v1/tokens" || r.Role != "operator" || r.Call != "credentials_of_kind" || r.Status != 200 {
		t.Errorf("Routes[9] = %+v", r)
	}
	if r := Routes[10]; r.Name != "issue_token" || r.Method != "POST" || r.Path != "/api/v1/tokens" || r.Role != "admin" || r.Call != "credential_problem" || r.Status != 201 {
		t.Errorf("Routes[10] = %+v", r)
	}
	if r := Routes[11]; r.Name != "revoke_token" || r.Method != "POST" || r.Path != "/api/v1/tokens/{name}/revoke" || r.Role != "admin" || r.Call != "credential_problem" || r.Status != 204 {
		t.Errorf("Routes[11] = %+v", r)
	}
}

func TestUnknownRoutes(t *testing.T) {
	svc := &fakeService{}
	if rec := do(svc, "operator", apiCase{method: "GET", target: "/api/v1/no-such-route"}); rec.Code != http.StatusNotFound {
		t.Errorf("unknown path: status %d", rec.Code)
	}
	if len(svc.calls) != 0 {
		t.Errorf("the service was called: %v", svc.calls)
	}
}

// TestServiceErrors: what a Service returns decides the status, and an
// unexpected error says nothing about its cause.
func TestServiceErrors(t *testing.T) {
	for _, c := range []struct {
		name string
		err  error
		want int
	}{
		{"not found", ErrNotFound, http.StatusNotFound},
		{"wrapped not found", fmt.Errorf("loading: %w", ErrNotFound), http.StatusNotFound},
		{"conflict", fmt.Errorf("storing: %w", ErrConflict), http.StatusConflict},
		{"unprocessable", fmt.Errorf("checking: %w", ErrUnprocessable), http.StatusUnprocessableEntity},
		{"anything else", errors.New("database password is hunter2"), http.StatusInternalServerError},
	} {
		t.Run(c.name, func(t *testing.T) {
			svc := &fakeService{err: c.err}
			rec := do(svc, "operator", getRoutingBaseline)
			wantProblem(t, rec, c.want)
			if strings.Contains(rec.Body.String(), "hunter2") {
				t.Fatalf("the response leaks the error: %s", rec.Body)
			}
		})
	}
}

func sameJSON(t *testing.T, got, want string) {
	t.Helper()
	var a, b any
	if err := json.Unmarshal([]byte(got), &a); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal([]byte(want), &b); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(a, b) {
		t.Fatalf("got %s, want %s", got, want)
	}
}

