	if err := json.Unmarshal([]byte(in), &wv); err != nil {
		t.Fatal(err)
	}
	var p problems
	d := decodeControlAuditEntry(wv, "", &p)
	if p.any() {
		t.Fatalf("a valid sample has problems: %v", p.list)
	}
	out, err := json.Marshal(encodeControlAuditEntry(d))
